export function pilotVegetation(x,z,seed){
 // World-fixed stands beyond the accepted 1km creek core. Never camera-thin.
 if(Math.max(Math.abs(x),Math.abs(z))<512)return {variant:seed<.5?0:1,scale:1,keep:true};
 const edge=Math.min(1,Math.max(0,(Math.max(Math.abs(x),Math.abs(z))-512)/100)),guard=edge*edge*(3-2*edge);
 const a=(1-Math.min(1,Math.max(0,(Math.hypot(x+600,z-630)-130)/150)))*guard;
 const b=(1-Math.min(1,Math.max(0,(Math.hypot(x-700,z+750)-160)/180)))*guard;
 const h=(n)=>{let k=Math.imul(Math.floor(x*13+n),374761393)^Math.imul(Math.floor(z*17-n),668265263);k=Math.imul(k^(k>>>13),1274126177);return((k^(k>>>16))>>>0)/4294967296;};
 if(a>0&&h(31)<a*.62)return {variant:2,scale:.84+h(53)*.22,keep:true};
 if(b>0&&h(91)<b){return {variant:3,scale:.34+h(71)*.23,keep:h(103)<.48};}
 return {variant:seed<.5?0:1,scale:1,keep:true};
}
